insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('a9b1c0e1-2bb4-42ff-a351-7d82e40830ea','en','yona-yona-dance','Yona Yona Dance','Yona Yona Dance is a viral dance challenge in Korea set to a song by Japanese singer Wada Akiko.','Japanese singer Wada Akiko released the song ''YONA YONA DANCE'' in September 2021, and its choreography became a huge dance-challenge trend on Korean TikTok and YouTube in 2022. Thanks to its catchy chorus and simple moves, people of all ages took part, and it became a popular entry in the ''Zero Two''-style dance meme family.','Japanese singer Wada Akiko''s song ''YONA YONA DANCE'' (released 2021) spread as a dance challenge in Korea in 2022.','A bright, upbeat dance challenge that anyone can easily follow.',NULL,array['요나요나 댄스','YONA YONA DANCE']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('607e04a0-26f6-4f57-837a-f355089ee6b9','en','bacchus-relieve-todays-fatigue-today','Bacchus – ''Relieve Today''s Fatigue Today''','''Relieve Today''s Fatigue Today'' is the tagline from a 1993 Dong-A Pharmaceutical ad for the energy drink Bacchus, built around ordinary working people.','In 1993, Dong-A Pharmaceutical launched its ''New Korean'' ad series for the energy drink Bacchus, featuring ordinary office workers and everyday citizens, with the tagline ''relieve today''s fatigue today.'' The understated copy and heartfelt storytelling made it a long-remembered ad, frequently parodied on comedy shows.','Dong-A Pharmaceutical had been barred from advertising Bacchus by government regulation from 1976 to 1993. When the ban lifted, it returned with the ''New Korean'' series featuring ordinary citizens, and the ''relieve today''s fatigue today'' tagline spread through episodes depicting quietly hardworking people such as bus-terminal staff and street cleaners. A total of 13 episodes were produced through 1997 to great acclaim. Its human-centered advertising style, spotlighting everyday laborers instead of glamorous celebrities, is credited with influencing later Korean public-service and corporate ads.','Can be quoted when comforting yourself at the end of a tiring day.',NULL,array['박카스 ''그날의 피로는 그날에''','그날의 피로는 그날에 푼다']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('6544a811-8f1c-4ba2-b84a-d9c57411440d','en','babymonster-batter-up-dance-challenge','BABYMONSTER ''Batter Up'' Dance Challenge','The Batter Up Dance Challenge has fans recreating the choreography from YG''s rookie girl group BABYMONSTER''s 2023 pre-debut single.','BABYMONSTER pre-debuted as a six-member group in November 2023 with the single ''BATTER UP,'' whose music video racked up 22.59 million YouTube views within a day of release, setting a record for the most-viewed K-pop debut music video in 24 hours. The ''BATTER UP DANCE CHALLENGE'' launched alongside it and quickly spread on social media.','Dance challenge for BABYMONSTER''s pre-debut single ''BATTER UP'' (released November 27, 2023).','Used as a challenge to cheer on a rookie girl group''s debut.',NULL,array['베이비몬스터 Batter Up 댄스 챌린지','배터업 챌린지','베이비몬스터 데뷔 챌린지']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('6796011b-7d0d-45d7-b520-37c9cc8cb290','en','im-gonna-be-king-of-the-pirates','I''m Gonna Be King of the Pirates','''I''m Gonna Be King of the Pirates'' is Luffy''s iconic catchphrase from One Piece, taken from its official Korean translation.','In volume 1 of One Piece, Luffy declares as he leaves home, ''I''m gonna be King of the Pirates!'' — rendered in the official Korean edition as ''해적왕이 될 남자다'' (''I am the man who will become King of the Pirates''). The line appears throughout every One Piece medium as Luffy''s signature phrase, and the author himself explained its significance in the SBS Q&A corner of volume 91.','One Piece manga, volume 1 (serialization began 1997), Luffy''s declaration as he sets sail.','Quoted and parodied as a way of declaring one''s own ambitions.',NULL,array['해적왕이 될 남자다','해적왕이 난 될테다','루피 시그니처 대사']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('722a94f5-c23d-49c7-a5bc-cb13df64f1e3','en','gettaman','Gettaman','Gettaman is a stick-figure Flash animation series serialized on the site Yeopgi House in the early 2000s.','Gettaman was a comic-hero stick-figure Flash animation series serialized on Yeopgi House during Korea''s early-2000s ''yeopgi'' (bizarre/absurd) content boom, created by an artist known as ''Taeja.'' It was one of the flagship series to emerge from the broader stick-figure (''Zzolaman''-style) animation craze that Korean teens enjoyed before webtoons existed. Early episodes had no fixed storyline and often veered into completely different directions after teasing ''to be continued,'' but the later ''Sinsegi Gettaman'' arc introduced a proper storyline. Creator Taeja stopped working after 2002 and disappeared without finishing the series; today, a YouTuber has restored some of the surviving Flash files as video uploads.','Gettaman was a comic-hero stick-figure Flash animation series serialized on Yeopgi House in the early 2000s.','Introduced as a niche reference known mainly to stick-figure animation enthusiasts.',NULL,array['겟타맨']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('fd67592e-1092-45ca-be3e-1e4457884c86','en','sakuranbo-challenge','Sakuranbo Challenge','The Sakuranbo Challenge is a cover-dance trend built around the chorus choreography of the 2003 Japanese song ''Sakuranbo,'' revived by Korean livestreamers in 2020.','Aika Otsuka''s 2003 song ''Sakuranbo'' was a nostalgic favorite for Korea''s early-2000s Cyworld generation. It resurfaced in 2020 after streamer Rallo frequently played it on broadcast, and BJ Yoo Hyedi of AfreecaTV popularized a chorus-section dance — closing her eyes, puffing her cheeks, and waving both hands — that spread among streamers as a cover-dance challenge.','Aika Otsuka''s song released in 2003; became a cover-dance trend among Korean livestreamers in 2020.','A good reference when talking about a charmingly quirky cover dance to an old song.',NULL,array['사쿠란보 챌린지','사쿠란보 커버댄스']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('321c3670-de0f-449d-b01f-e693b5a43033','en','gidle-tomboy-challenge','(G)I-DLE ''TOMBOY'' Challenge','The TOMBOY Challenge is a dance challenge built on (G)I-DLE''s signature song, which Billboard ranked the top K-pop song of the year.','''TOMBOY,'' the title track of (G)I-DLE''s first full album ''I NEVER DIE'' released in March 2022, was a massive hit that Billboard later named the No. 1 K-pop song of that year. It achieved a ''Perfect All-Kill'' on Korean music charts immediately after release, and a short dance challenge built around its choreography spread widely on social media.','Dance challenge for (G)I-DLE''s first full-album title track ''TOMBOY'' (released March 2022).','Used as a confident, hip girl-group dance challenge.',NULL,array['(여자)아이들 TOMBOY 챌린지','톰보이 챌린지']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('20f89fae-8af9-4b64-bc24-44d7521de547','en','god-childcare-diary','god''s Childcare Diary','god''s Childcare Diary is regarded as Korea''s first observational parenting show, following idol group god as they cared for a baby.','This program followed members of the idol group god as they took care of baby Han Jae-min, and it is considered the pioneer of Korean observational and parenting variety shows. It played a decisive role in establishing god as one of Korea''s most beloved ''nation''s group'' acts.','Aired on MBC from January 9, 2000 to May 12, 2001.','Referenced as the original example of observational parenting variety shows.',NULL,array['god의 육아일기','god 재민이 육아']::text[],'[{"text": "This parenting show totally has that original god''s Childcare Diary vibe.", "situation": "KakaoTalk"}, {"text": "When it comes to observational parenting shows, the original is god''s Childcare Diary.", "situation": "SNS comment"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('240a2533-1e51-47d0-84ab-6235fc20c9f3','en','knee-drop-guru-mureuppak-dosa','Knee-Drop Guru (Mureuppak Dosa)','Knee-Drop Guru is a talk-show segment in which host Kang Ho-dong plays a fortune-teller character who counsels guests on their life problems.','A segment of the talk show ''Golden Fishery'' that became a regular fixture on January 31, 2007. Kang Ho-dong takes on the shaman-like persona ''Mureuppak Dosa'' (Knee-Drop Guru) to give guests blunt life advice, and its no-holds-barred questioning style is credited with driving the late-2000s trend toward edgier, more confrontational variety shows.','MBC''s ''Golden Fishery'' segment ''Mureuppak Dosa'' (started January 31, 2007), hosted by Kang Ho-dong.','Referenced as the original example of frank life counseling delivered in variety-show style.',NULL,array['무릎팍도사','강호동 도사','무릎팍']::text[],'[{"text": "Give me some Knee-Drop Guru–style advice on my problem today.", "situation": "KakaoTalk"}, {"text": "This advice is totally as blunt as Knee-Drop Guru.", "situation": "SNS comment"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('6f7b24aa-6635-44bc-8feb-c14cdb0a2d22','en','do-re-mi-market','Do Re Mi Market','Do Re Mi Market is a segment of the show ''Amazing Saturday'' where contestants compete to correctly write down song lyrics for local market food prizes.','The flagship segment of ''Amazing Saturday,'' which first aired on tvN on April 7, 2018, is a cross-generational music variety format where contestants try to write down song lyrics correctly to win popular food from markets around the country. The show originally had two parts — ''Suckers'' Prison Life'' and ''Do Re Mi Market'' — but after the first part was dropped, Do Re Mi Market came to represent the entire show. Contestants comically mishearing and misspelling lyrics has become a recurring highlight of every episode.','Began as a segment of tvN''s ''Amazing Saturday'' on April 7, 2018.','Screenshots of hilariously misheard lyric captions are shared like memes.',NULL,array['도레미마켓','놀라운 토요일 도레미마켓','받아쓰기 게임']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('7bbbd44e-45f0-4fef-82ae-92627591f596','en','igatan-chew-tear-taste-enjoy','Igatan – ''Chew It, Tear It, Taste It, Enjoy It''','''Chew It, Tear It, Taste It, Enjoy It'' is the catchy jingle hook from an ad for the gum-health product Igatan, sung by trot singers Tae Jin-ah and Song Dae-gwan.','Around 2004, Myungin Pharm''s gum-care product Igatan cast trot singers Tae Jin-ah and Song Dae-gwan for a jingle built around the line ''chew it, tear it, taste it, enjoy it.'' The pair went on to serve as the product''s exclusive models for years, and the jingle became a nationally beloved earworm. Despite advertising a gum-health product, its upbeat melody has been fondly remembered for a long time.','Around 2004, Myungin Pharm''s Igatan TV commercial, featuring Tae Jin-ah and Song Dae-gwan.','''Chew it, tear it, taste it, enjoy it'' is quoted to mean thoroughly enjoying something.',NULL,array['이가탄 씹고 뜯고 맛보고 즐기고','씹고뜯고송']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('8b649529-6d16-4360-9aa0-18f99b332e1a','en','allday-project-wicked-challenge','ALLDAY PROJECT ''WICKED'' Challenge','The WICKED Challenge is a dance challenge based on rookie group ALLDAY PROJECT''s debut double-title track.','ALLDAY PROJECT, a five-member co-ed group from THEBLACKLABEL, debuted in June 2025, and a challenge based on the choreography for their double-title track ''WICKED'' spread across social media the moment they debuted. Its experimental beat and distinctive performance style drew major attention, helping the group achieve unusually strong popularity for a rookie act.','Dance challenge for THEBLACKLABEL rookie group ALLDAY PROJECT''s June 2025 debut track ''WICKED.''','Used when joining in on challenge content for a rookie idol group''s debut track.',NULL,array['WICKED 챌린지','올데이 프로젝트 위켓 챌린지']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('3ba293d3-de62-476a-b9db-19ff033ad788','en','pocari-sweat-la-la-la','Pocari Sweat ''La La La''','Pocari Sweat''s ''La La La'' is a jingle-driven 2001 ad shot in Santorini that made actress Son Ye-jin an icon of innocent, girl-next-door charm.','In 2001, a Pocari Sweat commercial starring actress Son Ye-jin was shot against the backdrop of Santorini, Greece, featuring the jingle ''tara-riri, la-la-la-la, if you like me.'' Her innocent, wholesome image — riding a bicycle in a white dress — made the ad a huge hit. Son Ye-jin was cast again in 2007 and 2008, making her the only ''Pocari Girl'' ever signed to the role twice.','2001 TV commercial for Dong-A Otsuka''s Pocari Sweat, starring Son Ye-jin.','People hum the ''la la la'' jingle to express a refreshing summer feeling.',NULL,array['포카리스웨트 라라라','손예진 포카리스웨트']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('5d2ca1ab-cf76-4f88-ad9a-8ca9dc4f3d03','en','turbo-hoesang-december','Turbo – ''Hoesang (December)''','''Hoesang (December)'' is Turbo''s most decorated song, topping Korean music chart shows a record 12 times after its 1997 release.','Released in October 1997 as the follow-up single from Turbo''s third album, ''Hoesang (December)'' topped Korean music chart shows a total of 12 times, making it the group''s most successful song. It stands as a defining hit from the early careers of Kim Jung-nam and Kim Jong-kook.','In 1997, Turbo competed with H.O.T. and Sechs Kies with the title track ''Goodbye Yesterday'' from their third album ''Born Again,'' taking No. 1 on KBS''s Gayo Top 10 for four consecutive weeks before releasing the follow-up ''Hoesang (December).'' ''Hoesang'' hit No. 1 on Gayo Top 10 on December 17 that year and kept the streak going, reportedly giving the two songs combined the record for the most consecutive No. 1 wins. Its mournful ballad-style melody and the vocal pairing of Kim Jong-kook and Kim Jung-nam made it one of the defining hits of the Korean music scene in late 1997.','Can be cited as a classic of late-1990s Korean dance-pop.',NULL,array['터보 ''회상''','회상(December)']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('c88bd049-f6b6-467c-814d-e256f610266d','en','top-blade-beyblade-craze','Top Blade (Beyblade) Craze','The Top Blade craze refers to the schoolyard spinning-top battle boom sparked by the Top Blade (Beyblade) toy line around 2002.','Top Blade (known internationally as Beyblade), a spinning-top toy line based on a Japanese anime, became hugely popular among Korean elementary schoolers around 2002, with top battles breaking out across schoolyards nationwide. Collecting and customizing the tops became a parallel trend.','The Japanese toy and anime franchise became popular in Korea around 2002.','Referenced as nostalgia for early-2000s elementary-school toy culture.',NULL,array['탑블레이드 열풍','베이블레이드','탑블레이드']::text[],'[{"text": "Top Blade was such a massive craze when we were kids.", "situation": "Group chat with old classmates"}, {"text": "Seeing this top takes me right back to the schoolyard.", "situation": "SNS comment"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('0f4f6bea-9b8d-4ba2-91d8-6e12ac11b564','en','reborn-rich-soonyang-group','Reborn Rich – Soonyang Group','Soonyang Group is the fictional conglomerate at the center of the 2022 JTBC drama ''Reborn Rich,'' which became a viewing sensation.','The JTBC drama ''Reborn Rich,'' which aired from November 2022, is a time-loop revenge story set around the fictional conglomerate ''Soonyang Group.'' It was one of the most talked-about shows of the second half of 2022 and repeatedly broke its own ratings records. The name and setup of Soonyang Group itself became a huge online talking point, spawning countless parodies and memes.','The fictional-conglomerate setting of the JTBC drama ''Reborn Rich'' (aired November 2022).','Cited when discussing chaebol-drama clichés or buzzworthy shows.',NULL,array['재벌집 막내아들 순양그룹','순양그룹']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('7a58b0aa-cf72-46b0-9a79-eccbf62ffab2','en','lijungddak','Lijungddak','Lijungddak, short for ''Liverpool belongs right in mid-table,'' is a football meme popularized by streamer Gamst''s parody song.','In March 2014, Sunderland manager Gus Poyet remarked that ''without Suárez, Liverpool would be a mid-table team,'' and the phrase was shortened in Korean to ''Lijungddak'' and spread from there. Known Manchester United fan and streamer Gamst rewrote singer Song Dae-gwan''s song ''Trendy Song'' into ''Lijungddak, Lijungddak, what a fun song,'' and it exploded in popularity through communities like DC Inside.','Derived from manager Gus Poyet''s 2014 remark; spread after streamer Gamst turned it into a parody song.','Used with background explanation when discussing football or Korean streamer culture.','It carries a put-down toward a specific football club, so using it in front of Liverpool fans can come across as rude. Gamst himself issued a public apology over it in 2018.',array['리중딱','리버풀은 중위권이 딱이야','리중딱 노래']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('0c318291-73e0-406a-84b7-744589bf4d25','en','sdm-studio-dress-makeup','SDM (Studio, Dress, Makeup)','SDM is a Korean wedding-industry term short for the near-mandatory pre-wedding package of studio photography, dress rental, and hair/makeup.','SDM is shorthand for the studio photo shoot, dress rental, and hair-and-makeup services that make up the standard Korean wedding preparation package, typically costing between roughly 2 million and 5 million won. In 2024, South Korea''s Presidential Committee on Aging Society and Population Policy pointed to high wedding costs as a factor behind the country''s low birth rate, putting renewed scrutiny on the opaque pricing structure of the SDM industry.','A near-mandatory package in Korea''s wedding industry, put back in the spotlight by 2024 low-birth-rate policy discussions.','Used to describe the financial burden of wedding preparation.',NULL,array['스드메','Studio Dress Makeup']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('c2f2ae25-7921-4012-8bf1-bce3119ff8bc','en','im-working-on-it-jageop-jungiya','''I''m Working On It'' (Jageop Jungiya)','''I''m Working On It'' is a catchphrase from a 2003 Samsung Anycall ad, used to describe making a romantic move on someone.','The line ''작업 중이야'' (''I''m working on it'') from Samsung Anycall''s 2003 phone commercial series became a popular way to describe pursuing someone romantically. At the time, the word ''작업'' (jageop, literally ''work'') itself was already a widely used slang term for making a romantic advance.','The line was delivered by actor Lee Seo-jin in a 2003 Samsung Anycall TV commercial. The ad, promoting a 1.3-megapixel camera phone, starred Lee Hyori just after her solo debut and rode the wave of her so-called ''Hyori Syndrome'' popularity to major buzz. The short line ''I''m working on it'' went on to be parodied across shows and ads for years, and even two decades later it continues to be revisited as a nostalgic commercial.','Used casually to describe someone making a move to show romantic interest.','It carries a nuance of treating romantic pursuit lightly, which can feel uncomfortable depending on context.',array['작업 중이야','작업중이야 애니콜']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('832c8209-30e8-48f2-82a9-f9c3a58d1cd5','en','face-taping','Face Taping','Face taping is a pre-makeup technique that uses clear tape to pull and lift the jawline and eye area.','Thin, transparent medical- or cosplay-grade tape is applied along the cheekbones or jawline to pull the face into a lifted shape before makeup is applied on top. It spread among TikTok beauty creators for offering an instant lifting effect without Botox or fillers.','A technique originally used in the cosplay industry, popularized as an everyday makeup tip by TikTok beauty creators around 2023.','Used to refer to the tip of pulling and contouring the face with tape instead of a cosmetic procedure.','Because the tape is applied directly to the skin, there is a risk of irritation or breakouts, so care is needed with prolonged use.',array['페이스 테이핑','테이핑 성형','face taping']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
